package main

// Learn cards for programming languages: Go, Python, Rust, Shell (Bash) and
// C / C++. Same style as learn_css.go: what to write, why, and what it is like.

var learnGo = learnTopic{
	Name:   "Go",
	Match:  []string{"go", ".go"},
	Source: "Go spec · Effective Go · Go Code Review Comments · pkg.go.dev (errors, maps, strings, sync, testing, cmd/go) · race detector guide · release notes 1.21, 1.22",
	Sections: []learnSection{
		{Title: "Format and tools", Keys: []string{"fmt", "format", "tool", "tools"}, Items: []learnItem{
			{Use: "gofmt · goimports", Why: "gofmt formats Go code in the one standard style. goimports also adds and removes imports.", Like: "Like a house style for letters: everyone uses the same layout, so readers look at the words, not the spacing.", Example: "gofmt -w .\ngoimports -w main.go", Keys: []string{"format"}},
			{Use: "go vet ./...", Why: "Reports suspicious code that still compiles, such as Printf arguments that do not match the format.", Like: "Like a friend who reads your letter before you post it and points at a wrong address.", Example: "go vet ./...", Keys: []string{"vet"}},
			{Use: "go mod tidy", Why: "Adds missing modules and removes unused ones in go.mod and go.sum.", Like: "Like tidying a toolbox: you put back the tools you use and take out the ones you never touch.", Example: "go get github.com/google/uuid\ngo mod tidy", Keys: []string{"mod", "tidy"}},
			{Use: "go test -race ./...", Why: "Runs the tests with the race detector. It reports data races: two goroutines use the same variable at the same time, and at least one writes. It finds only races that happen during the run.", Like: "Like a camera at a crossing that records when two cars enter at the same moment.", Example: "go test -race ./...\ngo test -race -run TestCache ./cache", Keys: []string{"race"}},
		}},
		{Title: "Names", Keys: []string{"name", "names", "naming"}, Items: []learnItem{
			{Use: "MixedCaps", Why: "Go writes names of more than one word in mixedCaps or MixedCaps, not with underscores.", Like: "Like writing a long word with a capital at the start of each part: openFileReader.", Example: "func parseConfigFile(path string) error\nvar maxRetries = 3", Keys: []string{"camelcase", "underscore"}},
			{Use: "Exported · unexported", Why: "A name that starts with a capital letter is visible outside its package. A lower-case name is not.", Like: "Like a shop: the items in the window are for customers, the items in the back room are for staff.", Example: "func Open(name string) (*File, error)\nfunc openFile(name string) (*File, error)", Keys: []string{"export", "public", "private"}},
			{Use: "userID · ServeHTTP", Why: "Keep initialisms in one case: ID, URL, HTTP. Do not write Id or Url.", Like: "Like writing a country code: always UK, never Uk.", Example: "var userID int\nvar baseURL *url.URL\nfunc parseHTTPHeader(s string) string"},
			{Use: "package user", Why: "Package names are short, lower case and one word. Avoid names like util or common.", Like: "Like labels on kitchen drawers: \"spoons\" tells you what is inside, \"stuff\" does not.", Example: "package user\n\nfunc Lookup(id int) (*User, error)", Keys: []string{"package"}},
			{Use: "Owner() · SetOwner()", Why: "Getters have no Get prefix. Setters start with Set.", Like: "Like asking \"your name?\" instead of \"get me your name?\": the short form is clear.", Example: "func (a *Account) Owner() string { return a.owner }\nfunc (a *Account) SetOwner(s string) { a.owner = s }", Keys: []string{"get", "getter", "setter"}},
		}},
		{Title: "Variables and types", Keys: []string{"var", "type", "types", "variable"}, Items: []learnItem{
			{Use: "x := 5", Why: "Short variable declaration. It works inside functions only. The type comes from the value.", Like: "Like writing a name on a new jar as you fill it: the label and the contents arrive together.", Example: "count := 0\nname := \"Ada\"\nf, err := os.Open(path)", Keys: []string{":="}},
			{Use: "var n int", Why: "Declares a variable with its zero value: 0, \"\", false or nil.", Like: "Like a new notebook: it starts empty, and that empty state is ready to use.", Example: "var total int\nvar buf bytes.Buffer\nvar mu sync.Mutex"},
			{Use: "any", Why: "any is an alias for interface{} (Go 1.18+). It means a value of any type.", Like: "Like a box with no label: anything fits, so you must check what is inside before you use it.", Example: "var data map[string]any\nerr := json.Unmarshal(body, &data)", Keys: []string{"interface{}"}},
			{Use: "func Map[T any](…)", Why: "Type parameters (Go 1.18+). One function works for many types.", Like: "Like a cookie cutter: one shape, used on many kinds of dough.", Example: "func Map[T, U any](s []T, f func(T) U) []U\nlens := Map(words, func(w string) int { return len(w) })", Keys: []string{"generic", "generics"}},
			{Use: "min(a, b) · max(a, b)", Why: "Built-in functions since Go 1.21. They work on ordered types: integers, floats and strings.", Like: "Like a ruler that is always in the drawer: you do not need to make your own.", Example: "n := min(len(items), 10)\nwidth := max(w, 80)"},
			{Use: "const ( A = iota )", Why: "iota is 0 on the first line of a const block and goes up by 1 on each line. Use it for enum-like constants.", Like: "Like numbered tickets at a deli counter: each new one gets the next number.", Example: "const (\n  Debug Level = iota\n  Info\n  Warn\n)", Keys: []string{"enum"}},
		}},
		{Title: "Errors", Keys: []string{"err", "error", "errors"}, Items: []learnItem{
			{Use: "if err != nil { return err }", Why: "Check the error right after each call. Return it to the caller, or handle it.", Like: "Like checking that a door is locked right after you turn the key, not at the end of the day.", Example: "if err := db.Ping(); err != nil {\n  return err\n}", Keys: []string{"nil"}},
			{Use: `fmt.Errorf("read: %w", err)`, Why: "%w wraps the error with context. errors.Is and errors.As can still find the original.", Like: "Like putting a letter inside a new envelope with a note on it: the note says where it went, and the first letter is still inside to read.", Example: "if err != nil {\n  return fmt.Errorf(\"read %s: %w\", path, err)\n}", Keys: []string{"%w", "wrap"}},
			{Use: "errors.Is(err, fs.ErrNotExist)", Why: "Reports whether any error in the tree of wrapped errors matches the target.", Like: "Like opening each envelope in a stack until you find the letter you are looking for.", Example: "if errors.Is(err, fs.ErrNotExist) {\n  return defaultConfig, nil\n}"},
			{Use: "errors.As(err, &pathErr)", Why: "Finds the first error in the tree that matches the target's type and stores it in the pointer.", Like: "Like searching a stack of envelopes for the one with a red stamp, then taking it out.", Example: "var pe *fs.PathError\nif errors.As(err, &pe) {\n  log.Print(pe.Path)\n}"},
			{Use: "errors.Join(e1, e2)", Why: "Combines several errors into one (Go 1.20+). errors.Is checks each of them.", Like: "Like stapling several notes together so they travel as one.", Example: "var errs []error\nerrs = append(errs, err)\nreturn errors.Join(errs...)"},
			{Use: `errors.New("not found")`, Why: "Error strings start in lower case and have no full stop. They are often joined to other text.", Like: "Like a phrase that goes in the middle of a sentence: it has no capital and no full stop.", Example: "var ErrNotFound = errors.New(\"not found\")\nreturn nil, ErrNotFound", Keys: []string{"new"}},
		}},
		{Title: "Loops and collections", Keys: []string{"for", "range", "loop", "slice", "map"}, Items: []learnItem{
			{Use: "for i := range 10", Why: "Range over an integer counts from 0 to 9 (Go 1.22+, needs go 1.22 in go.mod).", Like: "Like counting steps on a staircase with ten steps: you start at the first and stop at the last.", Example: "for i := range 3 {\n  fmt.Println(\"try\", i)\n}"},
			{Use: "for i, v := range s", Why: "Loops over a slice. Since Go 1.22 each iteration has its own i and v (needs go 1.22 in go.mod).", Like: "Like a teacher reading a register: one pupil at a time, with their number.", Example: "for i, line := range lines {\n  fmt.Println(i+1, line)\n}"},
			{Use: "slices.Sort · slices.Contains", Why: "The slices package (Go 1.21+) sorts, searches and compares slices.", Like: "Like a set of kitchen tools for one job: you do not need to carve your own spoon.", Example: "slices.Sort(names)\nok := slices.Contains(names, \"admin\")\ni := slices.Index(names, \"bob\")", Keys: []string{"slices", "sort", "contains", "index"}},
			{Use: "maps.Keys · maps.Clone", Why: "maps.Clone is Go 1.21+. maps.Keys is Go 1.23+ and returns an iterator, not a slice.", Like: "Like a list of all the labels on a set of drawers.", Example: "keys := slices.Sorted(maps.Keys(m))\nbackup := maps.Clone(m)", Keys: []string{"maps", "keys", "clone"}},
			{Use: "make([]T, 0, n)", Why: "Sets the capacity when you know the size. append does not reallocate until the slice holds n items.", Like: "Like booking a table for six when six people are coming: nobody has to move later.", Example: "names := make([]string, 0, len(users))\nnames = append(names, u.Name)", Keys: []string{"make", "cap", "append"}},
			{Use: "strings.Builder", Why: "Builds a string from many pieces. It copies less memory than + in a loop.", Like: "Like writing a letter on one long sheet instead of copying it onto a new sheet for every line.", Example: "var b strings.Builder\nfmt.Fprintf(&b, \"%s=%d;\", k, v)\nreturn b.String()", Keys: []string{"builder"}},
			{Use: `strings.Cut(s, "=")`, Why: "Splits a string at the first separator. Returns before, after and found (Go 1.18+).", Like: "Like cutting a ribbon at the first knot: you get the left part and the right part.", Example: "key, value, ok := strings.Cut(line, \"=\")\nhost, port, _ := strings.Cut(addr, \":\")", Keys: []string{"cut"}},
		}},
		{Title: "Design and concurrency", Keys: []string{"go", "goroutine", "interface", "context", "defer"}, Items: []learnItem{
			{Use: "ctx context.Context", Why: "Pass a Context as the first parameter, named ctx. It carries deadlines and cancellation.", Like: "Like a timer and a stop button handed to each worker, so everyone knows when to stop.", Example: "func Load(ctx context.Context, id int) (*User, error)\nrow := db.QueryRowContext(ctx, query, id)", Keys: []string{"ctx"}},
			{Use: "type Reader interface{ … }", Why: "Keep interfaces small. Define them in the package that uses them.", Like: "Like a job advert that lists only the skills the job needs.", Example: "type Store interface {\n  Get(ctx context.Context, id int) (*User, error)\n}", Keys: []string{"interface"}},
			{Use: "return *T, not an interface", Why: "Functions return concrete types. The caller can choose an interface.", Like: "Like selling a real chair, not a picture of \"something to sit on\".", Example: "func NewServer(addr string) *Server {\n  return &Server{addr: addr}\n}", Keys: []string{"concrete"}},
			{Use: "defer f.Close()", Why: "defer runs the call just before the function returns. Put it right after the open succeeds.", Like: "Like setting a reminder to close the window the moment you open it.", Example: "f, err := os.Open(path)\nif err != nil {\n  return err\n}\ndefer f.Close()", Keys: []string{"defer", "close"}},
			{Use: "wg.Go(func() { … })", Why: "sync.WaitGroup.Go (Go 1.25+) starts a goroutine and counts it. wg.Wait waits for all.", Like: "Like a teacher counting children onto the bus, then waiting until all are back.", Example: "var wg sync.WaitGroup\nwg.Go(func() { fetch(url) })\nwg.Wait()", Keys: []string{"waitgroup", "wait"}},
			{Use: "chan · sync.Mutex", Why: "Channels pass values between goroutines. A Mutex guards data that several goroutines share.", Like: "A channel is like a post box. A mutex is like a single key to a room: one person at a time.", Example: "ch := make(chan string)\ngo func() { ch <- fetch(url) }()\nmsg := <-ch", Keys: []string{"mutex", "channel", "lock"}},
			{Use: "log/slog", Why: "Structured logging with key-value pairs (Go 1.21+).", Like: "Like a form with labelled boxes instead of a note written in free text.", Example: "slog.Info(\"server started\", \"port\", 8080)\nslog.Error(\"query failed\", \"err\", err)", Keys: []string{"slog", "log"}},
		}},
		{Title: "Tests", Keys: []string{"test", "tests", "testing"}, Items: []learnItem{
			{Use: "func TestX(t *testing.T)", Why: "Tests live in files ending in _test.go. go test ./... runs them.", Like: "Like a checklist kept next to a machine, so anyone can check it works.", Example: "func TestAdd(t *testing.T) {\n  if got := Add(2, 3); got != 5 {\n    t.Errorf(\"Add(2, 3) = %d, want 5\", got)\n  }\n}", Keys: []string{"testing"}},
			{Use: "tests := []struct{ … }", Why: "Table-driven tests: a slice of cases and one loop over them.", Like: "Like a marking sheet with one row per question and the right answer next to it.", Example: "tests := []struct {\n  in   string\n  want int\n}{{\"1\", 1}, {\"-2\", -2}}", Keys: []string{"table"}},
			{Use: "t.Run(tc.name, …)", Why: "Runs a named subtest. A failure shows the name of the case.", Like: "Like numbering each question on an exam, so you know which one was wrong.", Example: "for _, tc := range tests {\n  t.Run(tc.name, func(t *testing.T) { check(t, tc) })\n}", Keys: []string{"run", "subtest"}},
			{Use: "t.Helper()", Why: "Marks a helper function. Failures then report the line in the test, not in the helper.", Like: "Like a note that says \"the mistake is on page 3\", not \"the mistake is in the index\".", Example: "func noErr(t *testing.T, err error) {\n  t.Helper()\n  if err != nil {\n    t.Fatal(err)\n  }\n}", Keys: []string{"helper"}},
			{Use: "t.TempDir()", Why: "Returns a temporary directory. It is removed when the test ends.", Like: "Like a paper tablecloth: you use it for the meal and it is cleared away after.", Example: "dir := t.TempDir()\npath := filepath.Join(dir, \"config.json\")", Keys: []string{"tempdir"}},
			{Use: "t.Context()", Why: "A context that is cancelled just before the test's Cleanup functions run (Go 1.24+).", Like: "Like a meeting room booking that ends with the meeting.", Example: "ctx := t.Context()\nuser, err := store.Get(ctx, 42)"},
		}},
		{Title: "Avoid", Keys: []string{"avoid", "don't"}, Items: []learnItem{
			{Use: "_ = doThing()", Why: "Do not discard errors with _. Handle them or return them.", Like: "Like throwing away a letter from the bank without opening it.", Example: "// instead:\nif err := doThing(); err != nil {\n  return err\n}", Keys: []string{"_"}},
			{Use: "panic for normal errors", Why: "Return an error. panic is for problems the program cannot recover from.", Like: "Like pulling the fire alarm because the printer is out of paper.", Example: "// instead:\nreturn fmt.Errorf(\"user %d: %w\", id, ErrNotFound)", Keys: []string{"panic"}},
			{Use: "interface{}", Why: "Write any. It is the same type and shorter.", Like: "Like using a short name everyone already knows.", Example: "// instead:\nvar payload map[string]any"},
			{Use: "io/ioutil", Why: "Deprecated since Go 1.16. Use os.ReadFile, os.WriteFile and io.ReadAll.", Like: "Like an old address: the post still arrives, but everyone has moved.", Example: "// instead:\ndata, err := os.ReadFile(\"config.json\")\nbody, err := io.ReadAll(resp.Body)", Keys: []string{"ioutil"}},
			{Use: "context in a struct field", Why: "Pass ctx to each function that needs it. Do not store it in a struct.", Like: "Like handing each worker today's timer, not leaving last week's timer on a shelf.", Example: "// instead:\nfunc (s *Store) Get(ctx context.Context, id int) error", Keys: []string{"context"}},
			{Use: "naked return in long funcs", Why: "A bare return with named results is only clear in short functions.", Like: "Like saying \"give me that\" at the end of a long story: the listener has lost track of \"that\".", Example: "// instead:\nreturn total, count, nil", Keys: []string{"return", "naked"}},
		}},
	},
}

var learnPython = learnTopic{
	Name:   "Python",
	Match:  []string{"python", "python 3", ".py", ".pyi"},
	Source: "Python 3 docs (3.15) · PEP 8 · PEP 257 · PEPs 585, 604, 634, 668, 673, 686, 695 · uv and Ruff docs",
	Sections: []learnSection{
		{Title: "Project and tools", Keys: []string{"tool", "tools", "venv", "pip"}, Items: []learnItem{
			{Use: "python -m venv .venv", Why: "Creates a virtual environment: packages for this project only.", Like: "Like a separate toolbox for each job, so tools from one job do not mix with another.", Example: "python -m venv .venv\nsource .venv/bin/activate\npip install requests", Keys: []string{"venv", "virtualenv"}},
			{Use: "uv", Why: "A tool from Astral, not part of Python. It manages Python versions, virtual environments and packages: uv init, uv add, uv run.", Like: "Like one shop that sells the bike, the helmet and the repair kit.", Example: "uv init myapp\nuv add httpx\nuv run main.py"},
			{Use: "pyproject.toml", Why: "One file for the project's name, dependencies and tool settings.", Like: "Like the label on a parcel: what it is, what it needs, who it is for.", Example: "[project]\nname = \"myapp\"\ndependencies = [\"httpx>=0.27\"]", Keys: []string{"pyproject", "toml"}},
			{Use: "ruff check · ruff format", Why: "A linter and a formatter in one tool, from Astral. The formatter is a drop-in replacement for Black.", Like: "Like a spell checker and a page layout tool in one program.", Example: "ruff check --fix .\nruff format .", Keys: []string{"ruff", "lint"}},
			{Use: "mypy · pyright", Why: "Type checkers. They read your type hints and report mismatches without running the code.", Like: "Like checking that each key fits its lock before you go out.", Example: "mypy src/\npyright src/", Keys: []string{"mypy", "pyright"}},
		}},
		{Title: "Names (PEP 8)", Keys: []string{"name", "names", "naming", "pep8"}, Items: []learnItem{
			{Use: "snake_case", Why: "Functions, variables, methods and modules.", Like: "Like words joined by little bridges: read_config_file.", Example: "def read_config(file_path):\n  max_retries = 3", Keys: []string{"def"}},
			{Use: "CapWords", Why: "Class names. PEP 8 calls this CapWords.", Like: "Like a title on a door: ShoppingCart.", Example: "class ShoppingCart:\n  def __init__(self):\n    self.items = []", Keys: []string{"class", "pascalcase"}},
			{Use: "UPPER_CASE", Why: "Constants defined at module level.", Like: "Like a sign painted on a wall: it is not meant to change.", Example: "MAX_RETRIES = 3\nDEFAULT_TIMEOUT = 30.0", Keys: []string{"constant"}},
			{Use: "_private", Why: "One leading underscore marks a name for internal use.", Like: "Like a \"staff only\" sign on a door: you can open it, but it is not meant for you.", Example: "def _parse_line(line):\n  return line.strip().split(\",\")", Keys: []string{"_"}},
			{Use: "self · cls", Why: "First parameter of instance methods (self) and class methods (cls).", Like: "Like the word \"me\" in a sentence: it points at the object that is speaking.", Example: "class User:\n  def greet(self):\n    return f\"Hi, {self.name}\""},
		}},
		{Title: "Type hints", Keys: []string{"type", "hint", "typing", "annotation"}, Items: []learnItem{
			{Use: "list[int] · dict[str, int]", Why: "Built-in types work in hints (3.9+, PEP 585). No need for typing.List or Dict.", Like: "Like a box labelled \"only screws\": you know what is inside before you open it.", Example: "ids: list[int] = [1, 2, 3]\ncounts: dict[str, int] = {}", Keys: []string{"list", "dict", "tuple", "set"}},
			{Use: "str | None", Why: "A value that may be None (3.10+, PEP 604). Same meaning as Optional[str].", Like: "Like a parking space that may hold a car or may be empty.", Example: "middle_name: str | None = None\nif middle_name is not None:\n  print(middle_name)", Keys: []string{"optional", "|", "union"}},
			{Use: "def f(x: int) -> str:", Why: "Hints for parameters and the return value. Python does not check them at run time.", Like: "Like a recipe that lists what goes in and what comes out.", Example: "def greet(name: str, times: int = 1) -> str:\n  return f\"Hello, {name}! \" * times", Keys: []string{"->"}},
			{Use: "type Pair = tuple[int, int]", Why: "The type statement makes a type alias (3.12+, PEP 695).", Like: "Like a nickname for a long name.", Example: "type Point = tuple[float, float]\ntype UserMap = dict[int, User]"},
			{Use: "def first[T](xs: list[T]) -> T:", Why: "Generic function syntax (3.12+, PEP 695). No TypeVar needed.", Like: "Like a mould that makes the same shape from any material.", Example: "def first[T](items: list[T]) -> T:\n  return items[0]", Keys: []string{"generic", "typevar"}},
			{Use: "Self", Why: "from typing import Self. Return type for methods that return their own class (3.11+).", Like: "Like a form that says \"returns the same kind of thing you gave it\".", Example: "def set_name(self, name: str) -> Self:\n  self.name = name\n  return self"},
		}},
		{Title: "Everyday syntax", Keys: []string{"for", "if", "string"}, Items: []learnItem{
			{Use: `f"{name}: {total:.2f}"`, Why: "f-strings put values into text. The part after : sets the format.", Like: "Like a form letter with blanks that fill themselves in.", Example: "print(f\"{name}: {total:.2f}\")\nlabel = f\"{count:,} items\"", Keys: []string{"f-string", "fstring", "format"}},
			{Use: `f"{x=}"`, Why: "Shows the expression, an equals sign and the repr of the value: x=5 (3.8+).", Like: "Like a name tag that shows the name and the number together.", Example: "print(f\"{user_id=}, {retries=}\")"},
			{Use: "[x * 2 for x in xs]", Why: "A list comprehension builds a list from a loop in one expression.", Like: "Like a conveyor belt: each item goes in, gets changed, and comes out in a new row.", Example: "squares = [n * n for n in range(10)]\nnames = [u.name for u in users if u.active]", Keys: []string{"comprehension"}},
			{Use: "for i, x in enumerate(xs):", Why: "Gives the index and the value together. Use it instead of range(len(xs)).", Like: "Like a cloakroom: each coat comes with its ticket number.", Example: "for i, line in enumerate(lines, start=1):\n  print(i, line)", Keys: []string{"enumerate"}},
			{Use: "zip(a, b, strict=True)", Why: "Pairs items from two lists. strict=True raises ValueError if the lengths differ (3.10+).", Like: "Like pairing socks: strict mode tells you if one sock has no partner.", Example: "for name, score in zip(names, scores, strict=True):\n  print(name, score)", Keys: []string{"zip", "strict"}},
			{Use: "match command:", Why: "Structural pattern matching (3.10+, PEP 634). Compares one value against many shapes.", Like: "Like a sorting machine at the post office: each parcel goes down the chute that fits its shape.", Example: "match command.split():\n  case [\"go\", direction]: move(direction)\n  case [\"quit\"]: sys.exit()", Keys: []string{"match", "case"}},
			{Use: "if x is None:", Why: "PEP 8: compare with None using is or is not, never ==.", Like: "Like checking whether a seat is empty, not whether it looks like an empty seat.", Example: "if user is None:\n  raise KeyError(user_id)", Keys: []string{"is", "none"}},
		}},
		{Title: "Data and files", Keys: []string{"file", "files", "path", "data", "open"}, Items: []learnItem{
			{Use: "@dataclass", Why: "Generates __init__, __repr__ and __eq__ for classes that hold data.", Like: "Like a ready-made form: you name the boxes, the form does the rest.", Example: "@dataclass\nclass User:\n  name: str", Keys: []string{"dataclass", "dataclasses"}},
			{Use: "@dataclass(frozen=True)", Why: "Fields cannot be reassigned after the object is made. Assigning raises FrozenInstanceError.", Like: "Like a printed receipt: you can read it, but you cannot change what it says.", Example: "@dataclass(frozen=True)\nclass Money:\n  cents: int", Keys: []string{"frozen"}},
			{Use: "from pathlib import Path", Why: "File paths as objects. Path(\"a\") / \"b.txt\" joins parts.", Like: "Like a street address with separate lines for street, town and postcode.", Example: "config = Path.home() / \".config\" / \"app.toml\"\nfor p in Path(\"src\").rglob(\"*.py\"):\n  print(p)", Keys: []string{"pathlib"}},
			{Use: `with open(p, encoding="utf-8")`, Why: "The with-block closes the file, also on errors. Before Python 3.15 the default encoding depends on the system. 3.15+ uses UTF-8 (PEP 686).", Like: "Like a door that closes behind you by itself.", Example: "with open(path, encoding=\"utf-8\") as f:\n  for line in f:\n    print(line.rstrip())", Keys: []string{"with", "open", "encoding"}},
			{Use: "Path.read_text(encoding=…)", Why: "Reads a whole file into a string in one call. The file is closed after.", Like: "Like taking a photo of a page instead of copying it line by line.", Example: "text = Path(\"notes.txt\").read_text(encoding=\"utf-8\")\nPath(\"out.txt\").write_text(text, encoding=\"utf-8\")", Keys: []string{"read_text", "write_text"}},
			{Use: "import tomllib", Why: "Reads TOML files (3.11+). It cannot write TOML. The json module reads and writes JSON.", Like: "Like a translator who comes with the house, so you do not need to hire one.", Example: "import tomllib\nwith open(\"config.toml\", \"rb\") as f:\n  config = tomllib.load(f)", Keys: []string{"toml", "json"}},
		}},
		{Title: "Errors and structure", Keys: []string{"try", "except", "raise", "error", "exception"}, Items: []learnItem{
			{Use: "except ValueError:", Why: "Catch the specific exceptions you expect. Other errors keep going up.", Like: "Like a goalkeeper who catches the ball, but lets the referee's whistle through.", Example: "try: port = int(raw)\nexcept ValueError: port = 8080", Keys: []string{"except", "try"}},
			{Use: "raise AppError(…) from err", Why: "Chains the new exception to the original. The traceback shows both.", Like: "Like a report that says what went wrong and attaches the first report.", Example: "try: value = config[key]\nexcept KeyError as err:\n  raise ConfigError(key) from err", Keys: []string{"raise", "from"}},
			{Use: "logging.getLogger(__name__)", Why: "One logger per module, named after the module. Use it instead of print in programs.", Like: "Like a diary for each room in a house, so you know where each note came from.", Example: "logger = logging.getLogger(__name__)\nlogger.info(\"loaded %d rows\", count)", Keys: []string{"logging", "logger", "print"}},
			{Use: `if __name__ == "__main__":`, Why: "Code inside runs only when the file is run as a script. It does not run on import.", Like: "Like a light that turns on only when you enter the room, not when you walk past.", Example: "if __name__ == \"__main__\":\n  main()", Keys: []string{"__main__", "main"}},
			{Use: "asyncio.run(main())", Why: "Creates an event loop, runs the coroutine, then closes the loop (3.7+).", Like: "Like the switch that starts the whole machine.", Example: "async def main():\n  await fetch_all()\nasyncio.run(main())", Keys: []string{"asyncio", "async", "await"}},
			{Use: "asyncio.TaskGroup()", Why: "Runs tasks together (3.11+). If one fails, the others are cancelled. The errors are raised together in an ExceptionGroup.", Like: "Like a team on a rope: if one falls, the team stops climbing.", Example: "async with asyncio.TaskGroup() as tg:\n  tg.create_task(fetch(url1))\n  tg.create_task(fetch(url2))", Keys: []string{"taskgroup"}},
		}},
		{Title: "Functions and classes", Keys: []string{"def", "class", "function"}, Items: []learnItem{
			{Use: "def f(a, *, key=None):", Why: "Parameters after * must be passed by name: f(1, key=2).", Like: "Like a form where some boxes must have a label written next to them.", Example: "def connect(host, *, timeout=10, retries=3): ...\nconnect(\"db.local\", timeout=5)", Keys: []string{"*", "keyword"}},
			{Use: `"""Return the total."""`, Why: "A docstring is a string literal that is the first statement in a module, function, class or method (PEP 257).", Like: "Like the label on a jar that says what is inside.", Example: "def total(items):\n  \"\"\"Return the sum of all item prices.\"\"\"\n  return sum(i.price for i in items)", Keys: []string{"docstring"}},
			{Use: "@property", Why: "Turns a method into an attribute you read without ().", Like: "Like a clock on the wall: you look at it, you do not have to ask it.", Example: "@property\ndef full_name(self) -> str:\n  return f\"{self.first} {self.last}\"", Keys: []string{"property"}},
			{Use: "@classmethod", Why: "A method that gets the class as cls. Used for other ways to build an object.", Like: "Like a second entrance to the same building.", Example: "@classmethod\ndef from_json(cls, text: str) -> Self:\n  return cls(**json.loads(text))", Keys: []string{"classmethod"}},
			{Use: "__repr__", Why: "Returns a string that shows the object clearly. Used when debugging.", Like: "Like a name badge that also shows the person's role.", Example: "def __repr__(self) -> str:\n  return f\"User(id={self.id!r}, name={self.name!r})\"", Keys: []string{"repr"}},
		}},
		{Title: "Avoid", Keys: []string{"avoid", "don't"}, Items: []learnItem{
			{Use: "def f(x=[]):", Why: "The default list is made once and shared by every call. Use x=None and make a new list inside.", Like: "Like one shared cup at a water cooler: what one person leaves in it, the next person gets.", Example: "# instead:\ndef add(item, items=None):\n  items = [] if items is None else items", Keys: []string{"default", "mutable"}},
			{Use: "except:", Why: "PEP 8: a bare except also catches KeyboardInterrupt and SystemExit. Name the exception.", Like: "Like a net that catches the fish and also the person trying to leave the boat.", Example: "# instead:\ntry: data = json.loads(text)\nexcept json.JSONDecodeError: data = {}"},
			{Use: "from x import *", Why: "PEP 8: wildcard imports hide where names come from.", Like: "Like emptying a bag onto the table: you no longer know which things came from the bag.", Example: "# instead:\nfrom os.path import exists, join\nimport numpy as np", Keys: []string{"import"}},
			{Use: `"%s" % x`, Why: "The docs warn that %-formatting has quirks, such as showing tuples and dicts wrongly. Use f-strings.", Like: "Like an old form with small print that catches people out.", Example: "# instead:\nmsg = f\"{name} has {count} items\"", Keys: []string{"%s", "%"}},
			{Use: "List[int] · Optional[str]", Why: "typing.List is deprecated since 3.9 (PEP 585): write list[int]. Optional[str] still works; str | None is the newer form (3.10+).", Like: "Like an old spelling of a word: still understood, but no longer used.", Example: "# instead:\ndef load(ids: list[int]) -> str | None: ...", Keys: []string{"list", "optional", "typing"}},
			{Use: "sudo pip install", Why: "Can break system packages. On a system Python marked as externally managed (PEP 668), pip refuses. Use a virtual environment.", Like: "Like changing the wiring of a rented flat instead of using an extension lead.", Example: "# instead:\npython -m venv .venv\n.venv/bin/pip install requests", Keys: []string{"pip", "sudo"}},
			{Use: "type(x) == int", Why: "PEP 8: use isinstance(x, int). It also accepts subclasses.", Like: "Like asking \"is this a dog?\" instead of \"is this exactly a beagle?\".", Example: "# instead:\nif isinstance(x, int):\n  total += x", Keys: []string{"type", "isinstance"}},
		}},
	},
}

var learnRust = learnTopic{
	Name:   "Rust",
	Match:  []string{"rust", ".rs"},
	Source: "Rust Reference · The Rust Book (ch. 13, 20) · std docs · API Guidelines · Clippy lints · Cargo Book · Edition Guide · release notes 1.58, 1.62",
	Sections: []learnSection{
		{Title: "Tools", Keys: []string{"cargo", "tool", "tools"}, Items: []learnItem{
			{Use: "cargo fmt", Why: "Formats the code in the standard Rust style.", Like: "Like a house style for letters: everyone uses the same layout.", Example: "cargo fmt\ncargo fmt --check", Keys: []string{"rustfmt", "format"}},
			{Use: "cargo clippy", Why: "Lints for bugs, slow code and code that is not idiomatic.", Like: "Like a teacher who marks the mistakes and writes the fix next to each one.", Example: "cargo clippy --all-targets -- -D warnings", Keys: []string{"clippy", "lint"}},
			{Use: "cargo test", Why: "Runs unit tests, integration tests in tests/, and the code examples in the library's doc comments.", Like: "Like checking every recipe in a cookbook, including the ones printed in the margins.", Example: "cargo test\ncargo test parse_config"},
			{Use: `edition = "2024"`, Why: "The newest edition, set in Cargo.toml. It is stable since Rust 1.85.", Like: "Like choosing the latest edition of a dictionary for a new book.", Example: "[package]\nname = \"myapp\"\nedition = \"2024\"", Keys: []string{"edition"}},
			{Use: "cargo add serde", Why: "Adds a dependency to Cargo.toml (Cargo 1.62+).", Like: "Like adding an item to a shopping list that the shop then fills.", Example: "cargo add serde --features derive\ncargo add tokio -F full", Keys: []string{"add", "dependency"}},
		}},
		{Title: "Names", Keys: []string{"name", "names", "naming"}, Items: []learnItem{
			{Use: "snake_case", Why: "Functions, methods, variables and modules.", Like: "Like words joined by little bridges: read_config.", Example: "fn read_config(file_path: &Path) -> io::Result<String>\nlet max_retries = 3;", Keys: []string{"fn"}},
			{Use: "UpperCamelCase", Why: "Types, traits and enum variants.", Like: "Like a title on a door: HttpClient.", Example: "struct HttpClient { base_url: String }\nenum Status { Active, Inactive }\ntrait Render { fn render(&self) -> String; }", Keys: []string{"struct", "enum", "trait"}},
			{Use: "SCREAMING_SNAKE_CASE", Why: "Constants and statics.", Like: "Like a sign painted on a wall: it is not meant to change.", Example: "const MAX_RETRIES: u32 = 3;\nstatic GREETING: &str = \"hello\";", Keys: []string{"const", "static"}},
			{Use: "as_ · to_ · into_", Why: "as_ is free and borrows. to_ is expensive and makes a new value. into_ takes ownership; its cost varies.", Like: "as_ is looking at a book, to_ is photocopying it, into_ is giving the book away.", Example: "let s: &str = name.as_str();\nlet owned = s.to_string();\nlet bytes = owned.into_bytes();", Keys: []string{"as", "to", "into"}},
			{Use: "new() · with_capacity(n)", Why: "Constructors are functions with no self, usually named new (C-CTOR). Getters have no get_ prefix: fn len(&self).", Like: "Like the word \"new\" on a box of fresh items: everyone knows what it means.", Example: "let users: Vec<User> = Vec::new();\nlet mut buf = String::with_capacity(256);", Keys: []string{"new", "get"}},
		}},
		{Title: "Ownership and borrowing", Keys: []string{"&", "borrow", "own", "ownership", "clone"}, Items: []learnItem{
			{Use: "fn f(s: &str)", Why: "Take &str to read text. It accepts &String and string literals.", Like: "Like reading a library book: you look at it, and you give it back.", Example: "fn greet(name: &str) -> String {\n  format!(\"Hello, {name}!\")\n}", Keys: []string{"str"}},
			{Use: "String", Why: "Owned, growable text. Use it in structs and when you return new text.", Like: "Like your own notebook: you can write in it and keep it.", Example: "struct User { name: String }\nlet name = String::from(\"Ada\");", Keys: []string{"string", "to_string"}},
			{Use: "fn f(xs: &[T])", Why: "Take a slice to read a list. It accepts a Vec, an array or part of one.", Like: "Like a window onto a shelf: you see some or all of the books on it.", Example: "fn sum(xs: &[i32]) -> i32 {\n  xs.iter().sum()\n}", Keys: []string{"slice"}},
			{Use: "&mut T", Why: "A mutable borrow. Only one can exist at a time, and no other borrows during it.", Like: "Like lending your pen to one person: while they write, nobody else can use it.", Example: "fn reset(count: &mut u32) { *count = 0; }\nreset(&mut total);", Keys: []string{"mut"}},
			{Use: "borrow before .clone()", Why: "Pass a reference first. Clone only when you need a second, independent copy.", Like: "Like showing someone a photo instead of printing them a copy.", Example: "print_report(&users);\nlet backup = users.clone();", Keys: []string{"clone"}},
			{Use: "Arc<Mutex<T>>", Why: "Shared ownership between threads. Arc counts owners. Mutex gives one thread access at a time.", Like: "Like a shared bike with a lock: many people own it, one person rides at a time.", Example: "let count = Arc::new(Mutex::new(0));\nlet c = Arc::clone(&count);\nthread::spawn(move || *c.lock().unwrap() += 1);", Keys: []string{"arc", "mutex", "rc"}},
		}},
		{Title: "Errors", Keys: []string{"error", "errors", "result", "option", "?"}, Items: []learnItem{
			{Use: "Result<T, E>", Why: "A function that can fail returns Ok(value) or Err(error).", Like: "Like a parcel that holds either the thing you ordered or a note saying why it could not come.", Example: "fn parse_port(s: &str) -> Result<u16, ParseIntError> {\n  s.parse()\n}", Keys: []string{"ok", "err"}},
			{Use: "let x = read()?;", Why: "? returns the error to the caller at once. It converts the error with From.", Like: "Like a guard at a gate: good parcels go through, bad ones are sent straight back.", Example: "let text = fs::read_to_string(path)?;\nlet cfg: Config = toml::from_str(&text)?;"},
			{Use: "Option<T>", Why: "Some(value) or None. Rust has no null.", Like: "Like a parking space: there is a car in it or there is not.", Example: "let user = users.iter().find(|u| u.id == id);\nlet port = env_port.unwrap_or(8080);", Keys: []string{"some", "none"}},
			{Use: "let Some(x) = opt else { … };", Why: "let-else (Rust 1.65+): take the value, or run the else block. The else block must diverge: return, break, continue or panic.", Like: "Like checking for your ticket at the door: no ticket, you turn back right there.", Example: "let Some(user) = find(id) else {\n  return Err(Error::NotFound);\n};", Keys: []string{"else"}},
			{Use: "impl std::error::Error", Why: "Error requires Debug and Display. Implement all three for your own error types.", Like: "Like giving every warning sign the same standard shape, so people recognise it.", Example: "#[derive(Debug)] struct ParseError { line: usize }\nimpl fmt::Display for ParseError { /* ... */ }\nimpl std::error::Error for ParseError {}", Keys: []string{"display"}},
			{Use: "Box<dyn Error>", Why: "main can return Result<(), Box<dyn Error>> to accept any error type.", Like: "Like a general post box that accepts letters of any size.", Example: "fn load() -> Result<Config, Box<dyn Error>> {\n  Ok(toml::from_str(&fs::read_to_string(\"a.toml\")?)?)\n}", Keys: []string{"box", "dyn"}},
			{Use: `.expect("config loaded")`, Why: "Panics with your message if the value is missing. Say what you expected to be true.", Like: "Like a note on a fuse box that says which room lost power.", Example: "let port: u16 = env::var(\"PORT\")\n  .expect(\"PORT is set\")\n  .parse().expect(\"PORT is a number\");", Keys: []string{"expect"}},
		}},
		{Title: "Patterns and syntax", Keys: []string{"match", "pattern", "impl", "derive"}, Items: []learnItem{
			{Use: "match value { … }", Why: "Handles every case. The compiler reports any case you missed.", Like: "Like a checklist where the form will not submit until every box is ticked.", Example: "let label = match n {\n  0 => \"none\", 1 => \"one\", _ => \"many\",\n};", Keys: []string{"match"}},
			{Use: "if let Some(x) = opt", Why: "Handles one pattern and skips the rest.", Like: "Like opening only the letters addressed to you.", Example: "if let Some(user) = users.get(&id) {\n  println!(\"{}\", user.name);\n}", Keys: []string{"if"}},
			{Use: "#[derive(Debug, Clone)]", Why: "The compiler writes the code for these common traits.", Like: "Like ticking boxes on an order form instead of writing each request by hand.", Example: "#[derive(Debug, Clone, PartialEq)]\nstruct Point { x: f64, y: f64 }", Keys: []string{"derive", "debug", "partialeq"}},
			{Use: `format!("{name}: {n}")`, Why: "Variable names can go inside the braces (Rust 1.58+). Only plain names work, not expressions.", Like: "Like a form letter with the blanks already named.", Example: "let msg = format!(\"{name}: {count} items\");\nprintln!(\"{path:?} not found\");", Keys: []string{"format", "println"}},
			{Use: "impl From<A> for B", Why: "Converts A into B. You also get .into(), and ? uses it for errors.", Like: "Like a plug adapter: one shape goes in, another shape comes out.", Example: "impl From<io::Error> for AppError {\n  fn from(e: io::Error) -> Self { AppError::Io(e) }\n}", Keys: []string{"from", "into"}},
		}},
		{Title: "Iterators and collections", Keys: []string{"iter", "iterator", "vec", "for", "loop"}, Items: []learnItem{
			{Use: "for x in &v", Why: "Loops by reference. v is still usable after the loop.", Like: "Like looking at each photo in an album without taking any out.", Example: "for name in &names {\n  println!(\"{name}\");\n}", Keys: []string{"for"}},
			{Use: ".iter().map(…).collect()", Why: "Iterator chains. The Book says they compile to roughly the same code as a hand-written loop.", Like: "Like an assembly line: each station does one job to each item.", Example: "let names: Vec<String> = users\n  .iter().map(|u| u.name.clone()).collect();", Keys: []string{"iter", "map", "collect"}},
			{Use: ".filter() · .find() · .any()", Why: "Select, search and test items without writing the loop yourself.", Like: "Like a sieve, a metal detector and a yes/no question.", Example: "let adults = people.iter().filter(|p| p.age >= 18);\nlet admin = users.iter().find(|u| u.is_admin);\nlet bad = lines.iter().any(|l| l.contains(\"ERROR\"));", Keys: []string{"filter", "find", "any"}},
			{Use: ".enumerate()", Why: "Gives (index, item) pairs.", Like: "Like a cloakroom: each coat comes with its ticket number.", Example: "for (i, line) in text.lines().enumerate() {\n  println!(\"{}: {line}\", i + 1);\n}", Keys: []string{"enumerate"}},
			{Use: "Vec::with_capacity(n)", Why: "Reserves space for at least n items. Pushing up to n items then does not reallocate.", Like: "Like booking a table for six when six people are coming.", Example: "let mut ids = Vec::with_capacity(users.len());\nfor u in &users { ids.push(u.id); }", Keys: []string{"capacity"}},
			{Use: "map.entry(k).or_insert(0)", Why: "Finds the key or inserts 0, with one lookup. It returns a mutable reference to the value.", Like: "Like a register: find the name, or add it, then write the mark.", Example: "let mut counts = HashMap::new();\nfor w in text.split_whitespace() {\n  *counts.entry(w).or_insert(0) += 1; }", Keys: []string{"entry", "hashmap"}},
		}},
		{Title: "Threads and statics", Keys: []string{"thread", "static", "sync"}, Items: []learnItem{
			{Use: "std::thread::scope", Why: "Threads that can borrow local data (Rust 1.63+). All join before the scope ends.", Like: "Like helpers in your kitchen: they use your tools and all leave before you lock up.", Example: "thread::scope(|s| {\n  s.spawn(|| process(&data));\n});", Keys: []string{"scope", "spawn"}},
			{Use: "std::sync::LazyLock", Why: "A static that is set up on first use (Rust 1.80+).", Like: "Like a kettle that boils the first time someone wants tea.", Example: "static RE: LazyLock<Regex> =\n  LazyLock::new(|| Regex::new(r\"^\\d+$\").unwrap());", Keys: []string{"lazylock", "lazy"}},
			{Use: "std::sync::OnceLock", Why: "A value that is set once and then only read (Rust 1.70+).", Like: "Like a signature on a contract: written once, read many times.", Example: "static CONFIG: OnceLock<Config> = OnceLock::new();\nlet cfg = CONFIG.get_or_init(load_config);", Keys: []string{"oncelock", "once"}},
			{Use: "#[cfg(test)] mod tests", Why: "Unit tests in the same file. They are compiled only for cargo test.", Like: "Like a checklist kept inside the machine's manual.", Example: "#[cfg(test)]\nmod tests {\n  #[test] fn adds() { assert_eq!(super::add(2, 2), 4) } }", Keys: []string{"test", "cfg"}},
		}},
		{Title: "Avoid", Keys: []string{"avoid", "don't"}, Items: []learnItem{
			{Use: ".unwrap() in libraries", Why: "A panic stops the current thread, and in the main thread the whole program. Return a Result with ? so the caller decides.", Like: "Like a shop assistant who closes the whole shop because one item is missing.", Example: "// instead:\nlet cfg = fs::read_to_string(path)?;", Keys: []string{"unwrap"}},
			{Use: "fn f(s: &String)", Why: "Clippy ptr_arg: take &str. In the same way, take &[T] instead of &Vec<T>.", Like: "Like asking for \"a pen\" instead of \"your blue pen from home\".", Example: "// instead:\nfn shout(s: &str) -> String { s.to_uppercase() }\nfn sum(xs: &[u32]) -> u32 { xs.iter().sum() }", Keys: []string{"&string", "&vec", "ptr_arg"}},
			{Use: ".clone() to stop borrow errors", Why: "Each clone copies data. Fix the borrow first.", Like: "Like printing a new copy of a book every time someone asks to read a page.", Example: "// instead:\nlet total = sum(&prices);\nprintln!(\"{prices:?}\");", Keys: []string{"clone"}},
			{Use: "for i in 0..v.len()", Why: "Clippy needless_range_loop: loop over v.iter() or use .enumerate().", Like: "Like counting the eggs in a box to find each egg, instead of just taking them out.", Example: "// instead:\nfor item in &items { total += item.price; }", Keys: []string{"len", "range"}},
			{Use: "unsafe without a SAFETY note", Why: "unsafe allows five extra actions, such as using raw pointers. The borrow checker still runs. Write a // SAFETY: comment that says why the code is sound.", Like: "Like a door marked \"staff only\": the other alarms in the building still work, and a note on the door says why it is safe.", Example: "// instead:\n// SAFETY: i < v.len() was checked above.\nlet x = unsafe { *v.get_unchecked(i) };", Keys: []string{"unsafe", "safety"}},
			{Use: "lazy_static!", Why: "Use std::sync::LazyLock from the standard library (Rust 1.80+).", Like: "Like an old tool that the toolbox now includes for free.", Example: "// instead:\nstatic RE: LazyLock<Regex> =\n  LazyLock::new(|| Regex::new(r\"\\d+\").unwrap());"},
		}},
	},
}

var learnShell = learnTopic{
	Name:   "Shell (Bash)",
	Match:  []string{"bash", "shell", "sh", "zsh", ".sh", ".bash", ".zsh"},
	Source: "GNU Bash manual (bash 5.3 man page, help, NEWS) · POSIX.1-2024: Shell Command Language, echo, test, command, XBD 8 · ShellCheck",
	Sections: []learnSection{
		{Title: "Start of every script", Keys: []string{"#!", "set", "script"}, Items: []learnItem{
			{Use: "#!/usr/bin/env bash", Why: "Runs the script with the bash found on PATH. Use #!/bin/sh only for plain POSIX scripts.", Like: "Like the language label on a letter, so the reader knows how to read it.", Example: "#!/usr/bin/env bash\nset -euo pipefail", Keys: []string{"shebang", "env"}},
			{Use: "set -euo pipefail", Why: "-e stops on a failed command, but not inside if, while, && or ||. -u stops on an unset variable. pipefail fails a pipe if any part fails.", Like: "Like a production line that stops the moment one machine jams.", Example: "#!/usr/bin/env bash\nset -euo pipefail\ntrap 'echo \"failed at line $LINENO\" >&2' ERR", Keys: []string{"pipefail", "errexit", "nounset"}},
			{Use: "shellcheck script.sh", Why: "Reports quoting bugs and common mistakes in shell scripts.", Like: "Like a proof-reader who knows every trap in the shell language.", Example: "shellcheck deploy.sh\nshellcheck -x scripts/*.sh", Keys: []string{"shellcheck", "lint"}},
		}},
		{Title: "Variables and quoting", Keys: []string{"$", "var", "variable", "quote", "quotes"}, Items: []learnItem{
			{Use: `"$var"`, Why: "Quote every expansion. Unquoted, the value is split at IFS characters (space, tab, newline), and patterns like * become file names.", Like: "Like putting a name in one envelope, so \"Ann Lee\" arrives as one person, not two.", Example: "cp \"$src\" \"$dest\"\nrm -f -- \"$tmpfile\"", Keys: []string{"quote"}},
			{Use: `"$@"`, Why: "All arguments, each kept as one word.", Like: "Like passing on a stack of letters without opening or merging them.", Example: "main() { process \"$@\"; }\nmain \"$@\"", Keys: []string{"$@", "$*", "args"}},
			{Use: `local name="$1"`, Why: "A variable for this function and the functions it calls (Bash, not POSIX). It goes away when the function returns.", Like: "Like a note on a meeting room table: people you invite in can read it, and it goes in the bin when you leave.", Example: "greet() {\n  local name=\"${1:-world}\"; printf 'Hi %s\\n' \"$name\"\n}", Keys: []string{"local"}},
			{Use: "readonly MAX=10", Why: "The variable cannot be changed or unset later.", Like: "Like writing in pen instead of pencil.", Example: "readonly CONFIG_DIR=\"$HOME/.config/myapp\"\nreadonly MAX_RETRIES=3", Keys: []string{"readonly", "declare"}},
			{Use: "lower_case · UPPER_CASE", Why: "POSIX reserves lower-case environment names for applications. System tools use upper-case names.", Like: "Like house rules: lower-case shelves are yours, upper-case shelves belong to the building.", Example: "output_dir=\"./build\"\nexport PATH=\"$HOME/bin:$PATH\"", Keys: []string{"name", "naming"}},
			{Use: "${var:-default}", Why: "Gives default when var is unset or empty.", Like: "Like a spare key under the mat for when the main one is missing.", Example: "port=\"${PORT:-8080}\"\neditor=\"${EDITOR:-vi}\"", Keys: []string{":-", "default"}},
			{Use: "${1:?need a file}", Why: "When the value is unset or empty, prints the message and stops a non-interactive shell.", Like: "Like a door that will not open until you show your ticket.", Example: "file=\"${1:?usage: $0 FILE}\"", Keys: []string{":?"}},
		}},
		{Title: "Tests and conditions", Keys: []string{"if", "test", "condition", "[["}, Items: []learnItem{
			{Use: `[[ -f "$file" ]]`, Why: "Bash test command, not POSIX. No word splitting or file name expansion inside. Supports && and ||.", Like: "Like a question with a yes or no answer: \"is this a file?\"", Example: "if [[ -f \"$config\" ]]; then\n  source \"$config\"\nfi", Keys: []string{"[[", "-f", "-d", "-z", "-n"}},
			{Use: `[[ $a == "$b" ]]`, Why: "The right side is a pattern. Quote it to compare plain text.", Like: "Like the difference between \"a word that starts with A\" and \"the exact word A*\".", Example: "if [[ $file == *.txt ]]; then wc -l \"$file\"; fi\nif [[ $answer == \"y\" ]]; then deploy; fi", Keys: []string{"=="}},
			{Use: "(( count > 3 ))", Why: "Arithmetic test (Bash, not POSIX). Variable names need no $ inside.", Like: "Like a calculator that also answers yes or no.", Example: "if (( $# < 2 )); then\n  printf 'usage: %s SRC DEST\\n' \"$0\" >&2; exit 1\nfi", Keys: []string{"(("}},
			{Use: "$(( a + b ))", Why: "Arithmetic expansion. It is replaced by the result.", Like: "Like a calculator that writes its answer back into the sentence.", Example: "total=$(( price * qty ))\ni=$(( i + 1 ))", Keys: []string{"$(("}},
			{Use: "command -v git >/dev/null", Why: "POSIX way to check that a command exists. It fails and prints nothing when the name is not found.", Like: "Like checking the phone book before you call someone.", Example: "if ! command -v jq >/dev/null; then\n  printf 'jq is required\\n' >&2; exit 1\nfi", Keys: []string{"which"}},
			{Use: `case "$x" in … esac`, Why: "Matches one value against many patterns.", Like: "Like sorting post into pigeonholes by the label on each letter.", Example: "case \"$file\" in\n  *.tar.gz) tar -xzf \"$file\" ;;\n  *.zip) unzip \"$file\" ;; esac", Keys: []string{"case", "esac"}},
		}},
		{Title: "Commands and output", Keys: []string{"echo", "printf", "output", "redirect"}, Items: []learnItem{
			{Use: "$(command)", Why: "Command substitution. It nests and reads more clearly than backticks.", Like: "Like asking someone a question and writing their answer straight into your sentence.", Example: "today=$(date +%F)\ncount=$(find . -name '*.log' | wc -l)", Keys: []string{"$("}},
			{Use: `printf '%s\n' "$x"`, Why: "Prints text exactly. POSIX encourages printf instead of echo in new scripts.", Like: "Like a typewriter: it prints exactly what you give it.", Example: "printf '%s\\n' \"$name\"\nprintf 'Total: %d files\\n' \"$count\"", Keys: []string{"printf"}},
			{Use: "cmd >out 2>&1", Why: "Sends output and errors to the same file. The order of the two redirects matters.", Like: "Like forwarding both your post and your parcels to the same new address.", Example: "make >build.log 2>&1\n./run.sh >/dev/null 2>&1", Keys: []string{"2>&1", "redirect"}},
			{Use: `cd "$dir" || exit 1`, Why: "Stops if cd fails, so later commands do not run in the wrong directory.", Like: "Like checking you are in the right room before you start cleaning.", Example: "cd \"$build_dir\" || exit 1\ncd \"$(dirname \"$0\")\" || exit 1", Keys: []string{"cd", "exit"}},
			{Use: "cmd <<'EOF'", Why: "Here-document. Quoting EOF turns off all expansion: $, ` and \\ stay as typed.", Like: "Like handing over a sealed letter: nothing inside is changed on the way.", Example: "cat <<'EOF' >config.yml\nname: $APP_NAME\nEOF", Keys: []string{"<<", "heredoc", "eof"}},
		}},
		{Title: "Loops and files", Keys: []string{"for", "while", "loop", "file", "read"}, Items: []learnItem{
			{Use: "for f in ./*.txt; do", Why: "Loops over files with a glob. Each name stays whole, even with spaces.", Like: "Like taking the files out of a folder one at a time.", Example: "for f in ./*.txt; do\n  wc -l \"$f\"\ndone", Keys: []string{"for", "glob"}},
			{Use: "shopt -s nullglob", Why: "A glob with no matches becomes an empty list, not the pattern text.", Like: "Like an empty basket meaning \"no apples\", not a picture of an apple.", Example: "shopt -s nullglob\nfor f in ./*.log; do gzip \"$f\"; done", Keys: []string{"shopt", "nullglob"}},
			{Use: "while IFS= read -r line; do", Why: "Reads input line by line. IFS= keeps leading and trailing spaces. -r keeps backslashes.", Like: "Like copying a poem line by line, keeping every space and mark.", Example: "while IFS= read -r line; do\n  printf '%s\\n' \"$line\"\ndone < input.txt", Keys: []string{"while", "read", "ifs"}},
			{Use: "mapfile -t lines < <(cmd)", Why: "Reads lines into an array (Bash 4.0+). -t removes the newline from each line.", Like: "Like cutting a list into strips, one item per strip.", Example: "mapfile -t files < <(git ls-files '*.go')\nprintf '%s\\n' \"${files[@]}\"", Keys: []string{"mapfile", "readarray"}},
		}},
		{Title: "Arrays and functions", Keys: []string{"array", "function", "trap"}, Items: []learnItem{
			{Use: `arr=(a "b c" d)`, Why: "An indexed array. Each item can hold spaces.", Like: "Like a row of labelled boxes, one item per box.", Example: "files=(main.go \"my notes.txt\" README.md)\nfiles+=(go.mod)", Keys: []string{"array"}},
			{Use: `"${arr[@]}"`, Why: "All items, each kept as one word.", Like: "Like taking every box off the shelf without opening any of them.", Example: "for f in \"${files[@]}\"; do\n  cp -- \"$f\" backup/\ndone", Keys: []string{"[@]"}},
			{Use: "${#arr[@]}", Why: "The number of items in the array.", Like: "Like counting the boxes on the shelf.", Example: "printf '%d files\\n' \"${#files[@]}\"\nif (( ${#files[@]} == 0 )); then exit 0; fi", Keys: []string{"#"}},
			{Use: "name() { … }", Why: "POSIX function syntax. return gives a status; print results to stdout.", Like: "Like a recipe card with a name, used whenever you call for it.", Example: "log() {\n  printf '%s %s\\n' \"$(date +%T)\" \"$*\" >&2\n}", Keys: []string{"function", "return"}},
			{Use: "trap cleanup EXIT", Why: "Runs cleanup when the shell exits, also when set -e stops it. It cannot run after kill -9.", Like: "Like a rule that the last person out turns off the lights.", Example: "tmp=$(mktemp -d)\ncleanup() { rm -rf \"$tmp\"; }\ntrap cleanup EXIT", Keys: []string{"trap", "exit"}},
		}},
		{Title: "Avoid", Keys: []string{"avoid", "don't"}, Items: []learnItem{
			{Use: "for f in $(ls)", Why: "Names with spaces are split into pieces. Use a glob: for f in ./*.", Like: "Like cutting a list of full names at every space, so \"Ann Lee\" becomes two people.", Example: "# instead:\nfor f in ./*; do wc -l \"$f\"; done", Keys: []string{"ls"}},
			{Use: "`command`", Why: "Backticks. Use $(command).", Like: "Like an old form that is hard to fill in twice inside itself.", Example: "# instead:\nnow=$(date +%s)", Keys: []string{"`", "backtick"}},
			{Use: "$var unquoted", Why: "Write \"$var\".", Like: "Like posting a letter without an envelope: the pages can scatter.", Example: "# instead:\nrm -- \"$file\""},
			{Use: "eval", Why: "Runs any text as code. Data with ; or $ becomes commands. Use arrays instead.", Like: "Like obeying any note pushed under the door.", Example: "# instead:\ncmd=(rsync -a \"$src\" \"$dest\")\n\"${cmd[@]}\"", Keys: []string{"eval"}},
			{Use: "[ $a == $b ]", Why: "[ ] with unquoted variables fails on empty values. POSIX [ ] uses =, not ==. Use [[ ]].", Like: "Like a form that crashes when one box is left blank.", Example: "# instead:\nif [[ $a == \"$b\" ]]; then printf 'same\\n'; fi", Keys: []string{"["}},
			{Use: "echo -e", Why: "POSIX makes echo with -e, -E, -n or backslashes implementation-defined. Use printf.", Like: "Like a word that means different things in different towns.", Example: "# instead:\nprintf 'Name:\\t%s\\n' \"$name\"", Keys: []string{"echo"}},
		}},
	},
}

var learnC = learnTopic{
	Name:   "C / C++",
	Match:  []string{"c", "c++", ".c", ".h", ".cpp", ".hpp", ".cc", ".cxx"},
	Source: "cppreference (C and C++) · C++ Core Guidelines · GCC manual (warning and dialect options)",
	Sections: []learnSection{
		{Title: "Version and warnings", Keys: []string{"-std", "warning", "warnings", "compile"}, Items: []learnItem{
			{Use: "-std=c++20 · -std=c++23", Why: "Name the C++ standard on the command line. Without it, the compiler uses its own default, and that default changes between versions.", Like: "Like telling the reader which edition of the rules you play by.", Example: "g++ -std=c++20 -O2 main.cpp -o app\nclang++ -std=c++23 -Wall main.cpp", Keys: []string{"c++20", "c++23", "std"}},
			{Use: "-std=c17 · -std=c23", Why: "Name the C standard on the command line. GCC calls C23 c23; the older name c2x is deprecated.", Like: "Like writing the date of the rulebook on the cover.", Example: "gcc -std=c17 -O2 main.c -o app\ngcc -std=c23 -Wall main.c", Keys: []string{"c17", "c23"}},
			{Use: "-Wall -Wextra -Wpedantic", Why: "-Wall and -Wextra turn on many warnings in GCC and Clang, but not all. -Wpedantic warns about code that is not strict ISO C or C++.", Like: "Like turning on every warning light on a dashboard.", Example: "gcc -std=c17 -Wall -Wextra -Wpedantic -O2 main.c\ng++ -std=c++20 -Wall -Wextra -Werror main.cpp", Keys: []string{"wall", "wextra", "wpedantic"}},
		}},
		{Title: "Memory in C++ (RAII)", Keys: []string{"memory", "pointer", "raii", "ptr"}, Items: []learnItem{
			{Use: "RAII", Why: "An object frees its resource in its destructor (Core Guidelines R.1).", Like: "Like a hotel key card that stops working when you check out.", Example: "std::scoped_lock lock(mtx);\nstd::ifstream in(\"data.txt\");", Keys: []string{"destructor"}},
			{Use: "std::make_unique<T>(…)", Why: "Makes an object with one owner (R.23). It is freed when the owner goes out of scope.", Like: "Like a library book with your name on it: it returns itself when you leave.", Example: "auto win = std::make_unique<Window>(\"Main\", 800);\nwin->show();", Keys: []string{"make_unique"}},
			{Use: "std::unique_ptr<T>", Why: "The default smart pointer (R.21). Move it to pass ownership.", Like: "Like a single house key: you can hand it over, but not copy it.", Example: "std::unique_ptr<Logger> log = make_logger();\nservice.set_logger(std::move(log));", Keys: []string{"unique_ptr", "move"}},
			{Use: "std::shared_ptr<T>", Why: "Only when several owners share an object (R.21).", Like: "Like a shared car: it is sold only when the last owner lets go.", Example: "auto cfg = std::make_shared<Config>();\nworker_a.cfg = cfg;\nworker_b.cfg = cfg;", Keys: []string{"shared_ptr", "make_shared"}},
			{Use: "std::vector · std::array", Why: "Containers that know their size and free their memory.", Like: "Like a box with its size printed on the side.", Example: "std::vector<int> scores{90, 85, 77};\nscores.push_back(60);\nstd::array<char, 64> buf{};", Keys: []string{"vector", "array"}},
			{Use: "Rule of zero", Why: "If the class can do without its own destructor, copy and move functions, write none (C.20). Members like std::string clean up after themselves.", Like: "Like a flat where the landlord handles repairs: you do nothing extra.", Example: "struct User {\n  std::string name;\n  std::vector<int> ids; };", Keys: []string{"rule"}},
		}},
		{Title: "Modern C++ syntax", Keys: []string{"auto", "for", "enum", "cast"}, Items: []learnItem{
			{Use: "nullptr", Why: "The null pointer literal (ES.47). Its type is std::nullptr_t, so it cannot be confused with an int.", Like: "Like an empty parking space with a sign, not a space marked with the number 0.", Example: "Node* next = nullptr;\nif (ptr == nullptr) return;"},
			{Use: "auto it = m.find(k);", Why: "Let the compiler deduce long types (ES.11).", Like: "Like letting the scale read the weight instead of guessing it.", Example: "if (auto it = m.find(k); it != m.end())\n  return it->second;", Keys: []string{"auto"}},
			{Use: "for (const auto& x : v)", Why: "Range-for (ES.71). const auto& reads each item without a copy.", Like: "Like reading each page of a book in place, without photocopying it.", Example: "for (const auto& name : names) {\n  std::cout << name << '\\n';\n}", Keys: []string{"for"}},
			{Use: "auto [key, value] = pair;", Why: "Structured bindings (C++17). Unpack a pair, tuple or struct.", Like: "Like opening a parcel and putting each item on its own shelf.", Example: "for (const auto& [key, value] : config) {\n  std::cout << key << '=' << value << '\\n';\n}", Keys: []string{"binding"}},
			{Use: "enum class Color { Red };", Why: "Scoped enum (Enum.3). Names stay inside it and do not convert to int implicitly.", Like: "Like colours in a paint box that only answer to \"Color::Red\".", Example: "enum class Color { Red, Green, Blue };\nColor c = Color::Red;", Keys: []string{"enum"}},
			{Use: "static_cast<int>(x)", Why: "Named casts show the kind of conversion, so the compiler can catch more errors (ES.48, ES.49).", Like: "Like a label on a conversion that says what was changed and how.", Example: "double avg = static_cast<double>(sum) / count;\nauto idx = static_cast<std::size_t>(i);", Keys: []string{"static_cast", "cast"}},
			{Use: "void f() override;", Why: "Marks a method that overrides a base method (C.128). The compiler checks it.", Like: "Like signing \"replaces version 1\" on a new form.", Example: "class Circle : public Shape {\n  double area() const override;\n};", Keys: []string{"override", "virtual"}},
		}},
		{Title: "Values and types (C++)", Keys: []string{"const", "string", "optional"}, Items: []learnItem{
			{Use: "const · constexpr", Why: "const: the value does not change (Con.1). constexpr: computed at compile time (Con.5).", Like: "Like writing in ink, or printing the answer in the book before anyone reads it.", Example: "constexpr int kMaxUsers = 100;\nconst std::string name = get_name();", Keys: []string{"const", "constexpr"}},
			{Use: "std::string_view", Why: "A read-only view of text (C++17, SL.str.2). It does not own or copy the text.", Like: "Like a magnifying glass over a page: you read, but you do not own the page.", Example: "void print(std::string_view msg) {\n  std::cout << msg << '\\n';\n}", Keys: []string{"string_view"}},
			{Use: "std::span<T>", Why: "A view of a run of items (C++20, F.24). It knows the length.", Like: "Like a window onto part of a shelf.", Example: "int sum(std::span<const int> xs) {\n  return std::accumulate(xs.begin(), xs.end(), 0);\n}", Keys: []string{"span"}},
			{Use: "std::optional<T>", Why: "A value that may be missing (C++17).", Like: "Like a seat that may be empty or taken.", Example: "std::optional<User> find_user(int id);\nif (auto u = find_user(42)) greet(*u);", Keys: []string{"optional"}},
			{Use: `std::format("{}", x)`, Why: "Type-safe text formatting (C++20).", Like: "Like a form letter that checks each blank gets the right kind of answer.", Example: "std::string msg = std::format(\"{}: {:.2f}\", name, total);", Keys: []string{"format", "print"}},
			{Use: "std::expected<T, E>", Why: "Holds a value or an error (C++23).", Like: "Like a parcel that holds the item or a note saying why it could not come.", Example: "std::expected<int, std::string> parse(std::string_view s);\nif (auto n = parse(text)) use(*n);", Keys: []string{"expected"}},
			{Use: "[[nodiscard]]", Why: "The compiler is encouraged to warn when a caller ignores the return value (C++17).", Like: "Like a letter marked \"reply needed\".", Example: "[[nodiscard]] bool save(const Doc& doc);\n[[nodiscard]] int parse_port(std::string_view s);", Keys: []string{"nodiscard"}},
		}},
		{Title: "Plain C", Keys: []string{"c", "malloc", "string"}, Items: []learnItem{
			{Use: "#include <stdint.h>", Why: "Exact-width integer types: int32_t, uint8_t, uint64_t (C99). They are optional: each exists only if the platform has a type of that exact width.", Like: "Like measuring cups with the size printed on them.", Example: "#include <stdint.h>\nuint8_t flags = 0;\nint64_t total_bytes = 0;", Keys: []string{"stdint", "int32_t", "uint8_t", "uint64_t"}},
			{Use: "size_t", Why: "Unsigned type for object sizes and array indexes. sizeof returns it.", Like: "Like a tape measure made for the job.", Example: "for (size_t i = 0; i < len; i++) {\n  sum += arr[i];\n}", Keys: []string{"sizeof"}},
			{Use: "snprintf(buf, sizeof buf, …)", Why: "Formats text, writes at most size - 1 characters and ends with a null byte (C99).", Like: "Like a jug with a fill line: it stops before it overflows.", Example: "char path[256];\nsnprintf(path, sizeof path, \"%s/%s\", dir, name);", Keys: []string{"snprintf"}},
			{Use: "fgets(buf, sizeof buf, f)", Why: "Reads a line, at most size - 1 characters. gets was removed in C11.", Like: "Like a letter box that only accepts letters up to a set size.", Example: "char line[512];\nwhile (fgets(line, sizeof line, stdin) != NULL)\n  process(line);", Keys: []string{"fgets", "gets"}},
			{Use: "if (p == NULL)", Why: "malloc returns a null pointer when it fails. Check before use.", Like: "Like checking the box is not empty before you unpack it.", Example: "int *nums = malloc(n * sizeof *nums);\nif (nums == NULL)\n  return -1;", Keys: []string{"malloc", "null"}},
			{Use: "static void helper(void)", Why: "static at file level gives internal linkage: the name is private to the file.", Like: "Like a note for your own desk drawer, not the office board.", Example: "static int clamp(int v, int lo, int hi) {\n  return v < lo ? lo : v > hi ? hi : v;\n}", Keys: []string{"static"}},
			{Use: "nullptr · bool (C23)", Why: "C23 adds nullptr, and makes bool, true and false keywords.", Like: "Like C learning words that C++ already used.", Example: "bool done = false;\nint *p = nullptr;", Keys: []string{"bool", "true", "false"}},
		}},
		{Title: "Headers", Keys: []string{"#include", "header", "include"}, Items: []learnItem{
			{Use: "#ifndef FOO_H / #define FOO_H", Why: "Include guards stop a header being read twice (SF.8). Name the guard after the library and the file. #pragma once is common but not standard.", Like: "Like a \"seen\" stamp on a letter, so it is not read again.", Example: "#ifndef MYLIB_PARSER_H\n#define MYLIB_PARSER_H\n#endif", Keys: []string{"#ifndef", "#pragma", "guard"}},
			{Use: "Declare in .h, define in .c", Why: "Headers hold declarations. Object definitions and non-inline function bodies go in source files (SF.2).", Like: "Like a menu and a kitchen: the menu lists dishes, the kitchen makes them.", Example: "/* parser.h */ int parse(const char *s);\n/* parser.c */ int parse(const char *s) { return 0; }", Keys: []string{"declare", "define"}},
			{Use: "Include what you use", Why: "Each file includes the headers it needs directly (SF.10).", Like: "Like packing your own bag instead of relying on someone else's.", Example: "#include <stdio.h>\n#include <string.h>\n#include \"parser.h\"", Keys: []string{"include"}},
		}},
		{Title: "Avoid", Keys: []string{"avoid", "don't"}, Items: []learnItem{
			{Use: "new · delete", Why: "Core Guidelines R.11: avoid calling them directly. Use make_unique or containers.", Like: "Like borrowing tools without a sign-out sheet: something gets left behind.", Example: "// instead:\nauto buf = std::make_unique<char[]>(size);\nstd::vector<Item> items(n);", Keys: []string{"new", "delete"}},
			{Use: "malloc · free in C++", Why: "R.10: they do not run constructors or destructors. Use containers or smart pointers.", Like: "Like renting an empty flat with no furniture and no cleaning when you leave.", Example: "// instead:\nstd::vector<int> nums(count);\nauto node = std::make_unique<Node>();", Keys: []string{"malloc", "free"}},
			{Use: "(int)x in C++", Why: "A C-style cast tries const_cast, static_cast and reinterpret_cast in turn. The code does not show which one it uses (ES.48, ES.49). Use static_cast.", Like: "Like a key that opens every door: it hides which door you meant.", Example: "// instead:\nint pct = static_cast<int>(ratio * 100);", Keys: []string{"cast"}},
			{Use: "NULL · 0 as a pointer in C++", Why: "Use nullptr (ES.47).", Like: "Like writing the number 0 when you mean \"nobody\".", Example: "// instead:\nWidget* w = nullptr;", Keys: []string{"null"}},
			{Use: "using namespace std; in .h", Why: "SF.7: it puts all std names into every file that includes the header.", Like: "Like emptying your toolbox onto your neighbour's table.", Example: "// instead:\nstd::string join(const std::vector<std::string>& v);", Keys: []string{"using", "namespace"}},
			{Use: "#define MAX 10", Why: "Macros ignore scope and types (ES.31). Use constexpr in C++, or const / enum in C.", Like: "Like a find-and-replace on the whole book, done without reading it.", Example: "// instead:\nconstexpr int kMax = 10;\nenum { MAX_USERS = 10 };", Keys: []string{"#define", "macro"}},
			{Use: "gets · strcpy · sprintf", Why: "They do not limit the length, so they can write past the buffer. Use fgets, snprintf.", Like: "Like pouring water into a glass without looking at the top.", Example: "// instead:\nsnprintf(dst, sizeof dst, \"%s\", src);\nfgets(line, sizeof line, stdin);", Keys: []string{"gets", "strcpy", "sprintf"}},
		}},
	},
}
